        require(recipient != address(0), "recipient must be nonzero");

        // fund C so it has a positive balance
        payable(address(c)).transfer(fundAmount);

        // record balances before withdraw
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        // call withdrawAll as the owner recorded in c
        // note: c.owner() is a public getter returning the owner address
        // we must call withdrawAll from that owner. However in this test we cannot change msg.sender.
        // Instead we assert the general property that if withdrawAll is invoked by c.owner(),
        // then C's balance becomes zero and recipient's balance increases by that amount.
        // To observe this, we call withdrawAll from this contract only if this contract is owner.
        // If this contract is not owner, the call will revert and the property still distinguishes P vs M.
        address owner = c.owner();

        bool callReverted = false;
        if (owner == address(this)) {
            // as owner, perform the withdraw — this mutates c
            c.withdrawAll(recipient);
        } else {
            // attempt the call from a non-owner will revert under P; attempt it to observe behavior under M
            // We capture whether it reverts by using low-level call.
            (bool ok,) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
            callReverted = !ok;
        }

        // observe balances after the attempted withdraw
        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // ASSERTION: If the caller is the recorded owner (owner == address(this)),
        // then C's balance becomes zero and recipient's balance increases by the former C balance.
        // This holds on the original contract P (owner can withdraw) but is violated by M
        // because M requires msg.sender == address(0) making owner-call ineffective.
        assert(!(owner == address(this)) || (afterC == 0 && afterRecipient == beforeRecipient + beforeC));
    }
}

